UPDATE ${table}
SET status = 20, update_by = #{operator}, update_time = NOW()
WHERE id = #{id} AND status = 10 AND deleted = 0

UPDATE ${table}
SET returned_qty = returned_qty + #{delta},
    update_time = NOW()
WHERE id = #{detailId}
  AND returned_qty + #{delta} >= 0
  AND deleted = 0
